import { userApiService } from 'src/services';
import { setWithExpiry, getWithExpiry } from 'src/utils/cacheHelper';
const sub_app_key = 'sub_app';

export default {
  methods: {
    async getSubscriptionFromServer() {
      try {
        const response = await userApiService.getSubscription();
        if (
          !response ||
          !response ||
          !Array.isArray(response) ||
          response.length == 0
        ) {
          return;
        }

        setWithExpiry(sub_app_key, this.getDoc2AppSubscription(response));
      } catch (err) {
        logError(err);
      } finally {
      }
    },

    getDoc2AppSubscription(data) {
      let doc2App_subsctiption_found = false;
      let dco2App_subsctiption = {};
      for (let subscription of data) {
        const apps = subscription.apps;
        for (let app of apps) {
          if (app.app_key === 'FELLOW_DOC2') {
            doc2App_subsctiption_found = true;
            dco2App_subsctiption = subscription;
            break;
          }
        }
        if (doc2App_subsctiption_found === true) {
          break;
        }
      }
      return dco2App_subsctiption;
    },

    getRemainingDays() {
      let days = -1;
      let subscription = this.getSubscription();

      if (!subscription) {
        return null;
      }

      let end_date = this.getDateFromServerDate(subscription.end_date);
      // let end_date = this.getDateFromServerDate('2022-06-09');
      const now = new Date().setHours(0, 0, 0, 0);
      days = this.datediff(now, end_date);
      return days;
    },

    datediff(now, end_date) {
      return Math.round((end_date - now) / (1000 * 60 * 60 * 24));
    },

    getDateFromServerDate(date) {
      var only_date = date.split(' ');
      return new Date(only_date[0]).setHours(0, 0, 0, 0);
    },

    async getsubscriptionRemainingDays() {
      let subscription_remaining_days = 0;
      try {
        subscription_remaining_days = this.getRemainingDays();
        if (subscription_remaining_days == null) {
          await this.getSubscriptionFromServer();
          subscription_remaining_days = this.getRemainingDays();
        }
      } catch (err) {
        logError(err);
      }
      return subscription_remaining_days;
    },

    subscriptionAlertShowDays() {
      return 30;
    },

    getSubscription() {
      let subscription = getWithExpiry(sub_app_key);

      if (
        !subscription ||
        !subscription.hasOwnProperty('start_date') ||
        !subscription.hasOwnProperty('end_date')
      ) {
        return null;
      }
       
      return subscription;
    },
  },
};
