              >
                <q-tooltip>{{ $t('import_log_filter_outbound') }}</q-tooltip>
              </q-icon>
              <q-icon v-else name="call_received" size="18px" color="blue-grey-5">
                <q-tooltip>{{ $t('inbound_received') }}</q-tooltip>
