<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { importApiService } from 'src/services';
import { buildImportLogDocSearch } from 'src/pages/Settings/Components/Import/importLogDocSearch';
import { useDropdownStore } from 'src/store/main';
import { getStatusIcon } from 'src/utils/general';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import {
  composeInboundAddress,
  getBranchPrefix,
  getCurrentApiRegion,
} from 'src/pages/api-base-url';
import { copyToClipboard as quasarCopyToClipboard } from 'quasar';
import { DocBitsTable } from 'src/components/Table';
import type {
  UnifiedTableColumn,
  SortEventPayload,
  PaginationChangePayload,
} from 'src/components/Table';
export default defineComponent({
  mixins: [helperMixin, dateUtils],
  components: { DocBitsTable },

  mounted: async function () {
    await this.initView();
  },

  computed: {
    v2Columns(): UnifiedTableColumn[] {
      return this.logColumns.map((col: dynamicObj) => ({
        name: col.field,
        label: col.label,
        field: col.field,
        align: 'left',
        // Derived/icon columns (outbound, reason, inbox) have no backend sort
        // field, so they opt out via col.sortable === false.
        sortable:
          col.sortable !== undefined ? col.sortable : col.field !== 'success',
      }));
    },
    v2TableFeatures() {
      return {
        sorting: true,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: false,
        resizable: true,
        pagination: true,
        columnReorder: false,
        // Row click opens the per-attachment detail (DOCB-13477).
        expandable: true,
      };
    },
    v2PaginationState() {
      return {
        sortBy: this.sort_by || 'created_on',
        descending: this.sort_order !== 'asc',
        page: this.current_page,
        rowsPerPage: this.page_size,
        rowsNumber: this.total_records,
      };
    },
  },

  methods: {
    async initView() {
      try {
        // Region-correct inbound address (DOCB-13674): a US org must receive
        // mail on its own regional inbound domain (us.<branch>.inbound…) so the
        // mail is delivered directly to the US import-email instance and both
        // documents AND the import log live in the org's region. EU stays on
        // the unprefixed default domain.
        this.receiveEmail = composeInboundAddress(
          getOrgId(),
          getCurrentApiRegion(),
          this.branch_name,
        );
        await this.loadData();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async copyToClipboard() {
      // Use Quasar's copyToClipboard (navigator.clipboard with an execCommand
      // fallback). The raw navigator.clipboard.writeText threw synchronously
      // when navigator.clipboard was undefined (non-secure context / webview) —
      // the .catch never fired, so nothing copied and no toast showed.
      if (!this.receiveEmail) {
        notify.error(this.$t('error_copy_to_clipboard'));
        return;
      }
      try {
        await quasarCopyToClipboard(this.receiveEmail);
        notify.success(this.$t('success_copy_to_clipboard'));
      } catch (err) {
        logError(err);
        notify.error(this.$t('error_copy_to_clipboard'));
      }
    },

    shortDocId(docId: string): string {
      // Keep the chip readable: first 8 chars + last 4 (full id in tooltip).
      if (!docId || docId.length <= 14) return docId;
      return `${docId.slice(0, 8)}…${docId.slice(-4)}`;
    },

    openLogDocument(docId: string) {
      const href = this.$router.resolve({
        path: '/dashboard',
        query: { search: buildImportLogDocSearch(docId) },
      }).href;
      window.open(href, '_blank');
    },

    async copyTraceId(traceId: string) {
      try {
        await quasarCopyToClipboard(traceId);
        notify.success(this.$t('success_copy_to_clipboard'));
      } catch (err) {
        logError(err);
        notify.error(this.$t('error_copy_to_clipboard'));
      }
    },

    attachmentStatus(att: dynamicObj): string {
      // Backend prefixes every deliberately-not-imported attachment error
      // with "Skipped" (signatures, inline images, non-importable types) —
      // shown as its own state so it doesn't read like a failure.
      if (att.success) return 'imported';
      const error = typeof att.error === 'string' ? att.error : '';
      return error.startsWith('Skipped') ? 'skipped' : 'failed';
    },

    attachmentStatusIcon(att: dynamicObj): string {
      const icons: dynamicObj = {
        imported: 'check_circle',
        skipped: 'remove_circle',
        failed: 'error',
      };
      return icons[this.attachmentStatus(att)];
    },

    attachmentStatusColor(att: dynamicObj): string {
      const colors: dynamicObj = {
        imported: 'positive',
        skipped: 'warning',
        failed: 'negative',
      };
      return colors[this.attachmentStatus(att)];
    },

    failedAttachmentNames(item: dynamicObj): string {
      const attachments = Array.isArray(item.attachments)
        ? item.attachments
        : [];
      if (!attachments.length) {
        return this.legacyAttachmentNames(item);
      }

      const failedNames: string[] = [];
      for (const attachment of attachments) {
        if (this.attachmentStatus(attachment) === 'imported'){
          continue;
        }
        if (attachment.name) {
          failedNames.push(attachment.name);
        }
      }
      return failedNames.length ? failedNames.join(', ') : '-';
    },

    legacyAttachmentNames(item: dynamicObj): string {
      if (Array.isArray(item.attachment_names)) {
        return item.attachment_names.join(', ');
      }
      return item.attachment_names || '-';
    },

    async downloadOriginalEmail(row: dynamicObj) {
      this.downloadingOriginal = row.trace_id;
      try {
        const blob = await importApiService.inboundLogOriginalEmail(
          row.trace_id,
        );
        if (!(blob instanceof Blob)) {
          notify.error(this.$t('import_log_original_email_unavailable'));
          return;
        }
        const url = URL.createObjectURL(
          new Blob([blob], { type: 'message/rfc822' }),
        );
        const link = document.createElement('a');
        link.href = url;
        link.download = `email-${row.trace_id}.eml`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
      } catch (err) {
        logError(err);
        notify.error(this.$t('import_log_original_email_unavailable'));
      } finally {
        this.downloadingOriginal = '';
      }
    },

    addInputEmailField() {
      this.inputEmails.push({ email: '', sub_org: '' });
    },

    deleteInputEmailField(index: number) {
      this.inputEmails.splice(index, 1);
    },

    filterSubOrgslistEvent(val: string, update: any) {
      if (!val) {
        update(() => {
          this.filterSubOrgsList = this.subOrgList;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filterSubOrgsList = this.subOrgList.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    async save() {
      try {
        this.validationTriggered = true;
        if (!this.validateEmails()) {
          return;
        }

        const data_json = {
          org_id: getOrgId(),
          senders: this.inputEmails,
          receiver: this.receiverEmail,
          senders_active: this.showEmailInputs,
          receiver_active: this.showEmailReceiver,
          notify_sender: this.notifySender,
          notify_on_receipt: this.notifyOnReceipt,
          error_notify_active: this.errorNotifyActive,
          error_notify_emails: this.errorNotifyEmails,
        };
        const response: any = await importApiService.inboundSave(data_json);

        // The endpoint returns HTTP 200 with a {success:false, message} envelope
        // when persistence fails. Treating that as success showed a green "Saved"
        // toast while the DB stayed empty — the exact symptom users reported.
        if (response && response.success === false) {
          throw { message: response.message || response.error };
        }

        notify.success(this.$t('success'));
      } catch (err: any) {
        // Surface the real backend message instead of a generic "error" so a
        // failed save is never mistaken for a successful one.
        notify.error(ApiExceptions.getErrorMessage(err as dynamicObj));
        logError('Error saving data:', err);
      }
    },

    async loadData() {
      try {
        const response: any = await importApiService.inboundLoad();

        if (!response.success) {
          throw { message: response.message };
        }

        // DOCB-11069: `response.data` is `undefined` for any org that has
        // never saved an inbound-email config yet — the backend answers
        // `{ success: true }` with no `data` key at all. Reading
        // `.email_senders` straight off `response.data` (without this
        // default) threw "Cannot read properties of undefined (reading
        // 'email_senders')" on every first-time page load. Default to `{}`
        // first so an empty/unsaved config renders a clean empty form
        // instead of crashing.
        const data = response.data || {};
        const senders = data.email_senders || [];
        this.receiverEmail = data.email_receiver || '';

        this.showEmailInputs =
          data.senders_active ?? !!(senders.length > 0 && senders[0]?.email);
        this.showEmailReceiver =
          data.receiver_active ?? this.receiverEmail !== '';
        this.notifySender = data.notify_sender ?? false;
        this.notifyOnReceipt = data.notify_on_receipt ?? false;
        this.errorNotifyEmails = data.error_notify_emails || '';
        this.errorNotifyActive = this.errorNotifyEmails !== '';

        // Ensure inputEmails always has at least one entry for the form
        this.inputEmails =
          senders.length > 0 ? senders : [{ email: '', sub_org: '' }];
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    validateEmails(): boolean {
      const hasEmptySenders = this.inputEmails.some(
        (email) => !email.email.trim(),
      );
      const hasEmptyReceiver = !this.receiverEmail.trim();

      if (hasEmptySenders && this.showEmailInputs) {
        notify.error(this.$t('CAN_NOT_PROCEED_ON_EMPTY_FIELD'));
        return false;
      }

      if (hasEmptyReceiver && this.showEmailReceiver) {
        notify.error(this.$t('CAN_NOT_PROCEED_ON_EMPTY_FIELD'));
        return false;
      }

      if (this.errorNotifyActive && !this.errorNotifyEmails.trim()) {
        notify.error(this.$t('CAN_NOT_PROCEED_ON_EMPTY_FIELD'));
        return false;
      }

      return true;
    },

    async showInboundEmailLogs() {
      try {
        this.loading = true;
        this.showEmailLogs = true;
        this.prepareTable();
        await this.loadLogData();
      } catch (error) {
        logError('Error loading email logs:', error);
        notify.error(this.$t('error'));
      } finally {
        this.loading = false;
      }
    },

    cleanupOnhide() {
      this.showEmailLogs = false;
    },

    prepareTable() {
      this.logRows = [];
      this.logColumns = [
        { label: '', field: 'expand', sortable: false },
        { label: this.$t('status'), field: 'success' },
        { label: this.$t('subject'), field: 'subject' },
        { label: this.$t('email'), field: 'from_email' },
        { label: this.$t('inbox'), field: 'inbox' },
        {
          label: this.$t('arrived_at'),
          field: 'created_on',
        },
        {
          label: this.$t('doc_count'),
          field: 'success_count',
        },
        {
          label: this.$t('failed_count'),
          field: 'failed_count',
        },
        {
          label: this.$t('direction'),
          field: 'outbound',
          sortable: false,
        },
        {
          label: this.$t('reason'),
          field: 'reason',
          sortable: false,
        },
        {
          label: this.$t('emaillog_filename'),
          field: 'attachment_names',
        },
      ];
    },

    toggleQuickFilter(which: 'errors' | 'inbound' | 'outbound') {
      if (which === 'errors') this.filterErrors = !this.filterErrors;
      // Inbound/Outbound are mutually exclusive: turning one on clears the other,
      // so there is no ambiguous "both on = show everything" state. Toggling the
      // active direction off returns to no-direction (show all).
      if (which === 'inbound') {
        this.filterInbound = !this.filterInbound;
        if (this.filterInbound) this.filterOutbound = false;
      }
      if (which === 'outbound') {
        this.filterOutbound = !this.filterOutbound;
        if (this.filterOutbound) this.filterInbound = false;
      }
      // Reset to the first page so the filtered result starts at the top.
      this.current_page = 1;
      this.offset = 0;
      this.loadLogData();
    },

    async loadLogData(order_by?: string, order_by_direction?: string) {
      this.loading = true;
      this.sort_by = order_by || 'created_on';
      this.sort_order = order_by_direction || 'desc';

      this.request_params = {} as dynamicObj;
      this.request_params['org_id'] = getOrgId();
      this.request_params['offset'] = this.offset;
      this.request_params['limit'] = this.page_size;
      this.request_params['order_by_direction'] = order_by_direction || 'desc';
      this.request_params['order_by_field'] = order_by || 'created_on';
      this.request_params['filter'] = this.filter;
      // Quick filters → backend query params. Errors = failed imports only.
      // Inbound/Outbound are mutually exclusive (see toggleQuickFilter), so at
      // most one is active: exactly one → that direction, neither → show all.
      if (this.filterErrors) {
        this.request_params['success_status'] = false;
      }
      if (this.filterInbound && !this.filterOutbound) {
        this.request_params['direction'] = 'inbound';
      } else if (this.filterOutbound && !this.filterInbound) {
        this.request_params['direction'] = 'outbound';
      }

      try {
        const response = await importApiService.inbounLoadLogs(
          this.request_params,
        );

        if (!response.data) {
          throw { message: response.message };
        }

        this.total_records = response.element_count || 0;
        this.logRows = response.data.map((item: any, index: number) => ({
          id: item.id ?? `${this.offset + index}`,
          from_email: item.sender || '-',
          subject: item.subject || '-',
          inbox: item.inbox || '-',
          attachment_names: this.failedAttachmentNames(item),
          created_on: item.created_on
            ? this.formatDateAccordingToPreference(item.created_on)
            : '-',
          success_count: item.success_count || 0,
          failed_count: item.failed_count || 0,
          success: item.success_count > 0 || false,
          // Outbound visibility (DOCB-12853): receipt/notify mails we sent back,
          // plus the friendly failure reason. Backend ships these on /inbound_logs;
          // they default to false/'-' on rows from a pre-migration backend.
          receipt_sent: !!item.receipt_sent,
          notify_sent: !!item.notify_sent,
          reason: item.reason || '-',
          reason_raw: item.reason_raw || item.reason || '',
          direction: item.direction || 'inbound',
          // Per-attachment detail + correlation id for the expandable row
          // (DOCB-13477); default safely on rows from a pre-migration backend.
          trace_id: item.trace_id || '',
          attachments: Array.isArray(item.attachments) ? item.attachments : [],
        }));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async handleSort(payload: SortEventPayload) {
      if (payload.direction === null) {
        this.sort_by = 'created_on';
        this.sort_order = 'desc';
      } else {
        this.sort_by = payload.column;
        this.sort_order = payload.direction;
      }
      this.current_page = 1;
      this.offset = 0;
      await this.loadLogData(this.sort_by, this.sort_order);
    },

    async handlePagination(payload: PaginationChangePayload) {
      this.current_page = payload.page;
      this.page_size = payload.rowsPerPage;
      this.offset = this.page_size * (this.current_page - 1);
      await this.loadLogData(this.sort_by, this.sort_order);
    },
  },

  setup() {
    const branch_name = getBranchPrefix();
    const dropdown_store = useDropdownStore();
    const { subOrgList, sub_org_list_loading } = storeToRefs(dropdown_store);
    const filterSubOrgsList: any = ref(dropdown_store.subOrgList);
    return {
      loading: ref(false),
      receiveEmail: ref(''),
      branch_name,
      showEmailInputs: ref(false),
      inputEmails: ref([{ email: '', sub_org: '' }] as {
        email: string;
        sub_org: string;
      }[]),
      showEmailReceiver: ref(false),
      receiverEmail: ref(''),
      notifySender: ref(false),
      notifyOnReceipt: ref(false),
      errorNotifyActive: ref(false),
      errorNotifyEmails: ref(''),
      filterSubOrgsList,
      subOrgList,
      sub_org_list_loading,
      validationTriggered: ref(false),
      showEmailLogs: ref(false),
      downloadingOriginal: ref(''),
      logRows: ref([] as dynamicObj[]),
      logColumns: ref([] as dynamicObj[]),
      total_records: ref(0),
      request_params: ref({} as dynamicObj),
      offset: ref(0),
      page_size: ref(10),
      current_page: ref(1),
      sort_by: ref(''),
      sort_order: ref(''),
      filter: ref(''),
      filterErrors: ref(false),
      filterInbound: ref(false),
      filterOutbound: ref(false),
      getStatusIcon,
    };
  },
});
</script>
