<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { storeToRefs } from 'pinia';
import { useDropdownStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { importApiService } from 'src/services';
import CryptoJS from 'crypto-js';
import { filterApiDocTypes } from 'src/utils/docTypeFilter';
import { runtimeEnv } from 'src/config/runtime-env';
const { AES, mode, enc, pad } = CryptoJS;

/**
 * Required connection inputs, each with the translation key of its label so a
 * refusal can say which input is empty. Other model keys are optional; the
 * archive path has its own check.
 */
const REQUIRED_FIELDS: Record<string, string> = {
  ftp_type: 'type',
  server: 'server',
  port: 'port',
  username: 'username',
  password: 'password',
};

/**
 * CORE-6168: what the password input shows for a password that is stored but
 * not re-entered. All asterisks, so `syncPasswordFromInput` never adopts it.
 */
const STORED_PASSWORD_MASK = '********';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    selected_model: {} as any,
    api_key: { type: String, default: '' },
  },
  components: {},
  data() {
    return {};
  },
  setup() {
    const dropdown_store = useDropdownStore();
    const { ftp_types, subOrgList, sub_org_list_loading, active_doc_type_list } =
      storeToRefs(dropdown_store);
    const filterSubOrgsList: any = ref(dropdown_store.subOrgList);
    dropdown_store.prepareDocTypeAndSubTypesList();

    return {
      EMAIL_ENCRYPTION_KEY: ref(''),
      subOrgList,
      sub_org_list_loading,
      filterSubOrgsList,
      ftp_types,
      active_doc_type_list,
      docTypeOptions: ref([] as any),
      selectedDocType: ref(null as any),
      loading: ref(false),
      missingFields: ref([] as string[]),
      model: ref({} as any),
      row_id: ref(''),
      errors: ref({} as { [k: string]: any }),
      api_key_ref: ref(''),
      validationTriggered: ref(false),
      folderOptions: ref([] as any),
      folderOptionsLoading: ref(false),
      maskedPassword: ref(''),
      actualPassword: ref(''),
      hasStoredPassword: ref(false),
      storedPassword: ref(''),
    };
  },
  mounted: function () {
    const EMAIL_ENCRYPTION_KEY = runtimeEnv('APP_VUE_EMAIL_ENCRYPTION_KEY');
    if (EMAIL_ENCRYPTION_KEY == undefined) {
      throw 'Missing EMAIL_ENCRYPTION_KEY env - unable to load';
    }
    this.EMAIL_ENCRYPTION_KEY = EMAIL_ENCRYPTION_KEY;
    this.initView();
  },

  computed: {
    // CORE-1468/CORE-6319: the service stamps deactivated_by with this marker
    // when the retry window ran out (as opposed to a user switching it off).
    wasAutoDeactivated(): boolean {
      // initView's empty-value loop turns `is_active: false` into '' — any
      // falsy value here means "off".
      return (
        this.model &&
        !this.model['is_active'] &&
        this.model['deactivated_by'] === 'system:auto-deactivate'
      );
    },
  },

  methods: {
    initView() {
      this.docTypeOptions = filterApiDocTypes(this.active_doc_type_list);
      this.api_key_ref = this.api_key;

      this.row_id = this.selected_model.hasOwnProperty('id')
        ? this.selected_model.id
        : '';

      this.model = JSON.parse(JSON.stringify(this.selected_model));
      for (let [name, value] of Object.entries(this.model)) {
        if (!value) {
          this.model[name] = '';
        }
      }

      // CORE-6168: never decrypt the stored password into the form. CryptoJS
      // does not fail on a ciphertext it cannot decrypt, it returns garbage,
      // and saving re-encrypted that garbage over the stored password on every
      // edit. The service now only says a password is set (`has_password`);
      // an older one still returns the ciphertext, which is sent back as is.
      this.storedPassword = this.model['password'] || '';
      this.hasStoredPassword =
        this.model['has_password'] === true || this.storedPassword !== '';
      this.actualPassword = '';
      this.maskedPassword = this.hasStoredPassword ? STORED_PASSWORD_MASK : '';
      this.model['password'] = '';
      this.model['move_after_import'] = this.model['move_after_import']
        ? true
        : false;
      this.model['ignore_certificate'] = this.model['ignore_certificate']
        ? true
        : false;
      this.model['include_subfolder_content'] = this.model[
        'include_subfolder_content'
      ]
        ? true
        : false;
      this.model['server'] = this.model['server_url'];

      // CORE-1468: the empty-value loop above turned 0/null into '' — restore
      // numbers with the service's defaults.
      this.model['retry_interval'] = Number(this.model['retry_interval']) || 60;
      this.model['retry_duration'] = Number(this.model['retry_duration']) || 48;
      this.model['notification_emails'] = this.model['notification_emails'] || '';

      if (this.model['additional_attributes']) {
        try {
          const raw = this.model['additional_attributes'];
          const attrs = typeof raw === 'string' ? JSON.parse(raw) : raw;
          this.selectedDocType = attrs.doc_type || null;
          if (typeof raw !== 'string') {
            this.model['additional_attributes'] = JSON.stringify(raw);
          }
        } catch {
          this.selectedDocType = null;
        }
      }

      this.fetchFolders();
      if (!this.row_id) {
        this.resetForm();
      }
    },

    resetForm() {
      this.selectedDocType = null;
      this.hasStoredPassword = false;
      this.storedPassword = '';
      this.actualPassword = '';
      this.maskedPassword = '';
      this.model = {
        username: '',
        password: '',
        server: '',
        port: '22',
        default_directory: '',
        file_name_matching_patterns: '',
        ftp_type: 'SFTP',
        ignore_certificate: false,
        sub_org_id: '',
        move_after_import: false,
        include_subfolder_content: false,
        destination_directory: '',
        import_directory: '',
        additional_attributes: '',
        retry_interval: 60,
        retry_duration: 48,
        notification_emails: '',
      };
    },

    copyPassword() {
      this.maskedPassword = '*'.repeat(this.actualPassword.length);
      navigator.clipboard.writeText(this.actualPassword).then(() => {
        notify.success(this.$t('password_copy_msg'));
      });
    },

    /**
     * DOCB-14502: take the password the user can actually see.
     *
     * The input is bound to `maskedPassword`, and `model.password` /
     * `actualPassword` are only written in `handleBlur`. A password that was
     * filled in but never blurred — browser autofill, a password manager, or
     * pressing Save straight from the field — therefore left the model empty
     * while the input visibly showed a value, and validation reported
     * "Field is required" over a form that looked complete. Reported on a
     * freshly created connection, where nothing else can be empty.
     *
     * The one thing that must NOT be adopted is our own mask: after a blur the
     * input shows `*` repeated, and treating that as the password would replace
     * a real credential with asterisks. Anything else visible is a real entry.
     */
    syncPasswordFromInput() {
      const shown = this.maskedPassword ?? '';
      const isOwnMask =
        shown.length > 0 && shown === '*'.repeat(shown.length);
      if (shown && !isOwnMask) {
        this.actualPassword = shown;
        this.model['password'] = shown;
      }
    },

    handleFocus(event: Event) {
      this.maskedPassword = '';
    },
    handleBlur(event: Event) {
      const target = event.target as HTMLInputElement;
      if (!target.value && this.hasStoredPassword) {
        // Focused and left without typing: keep the stored password.
        this.maskedPassword = STORED_PASSWORD_MASK;
        this.actualPassword = '';
        this.model['password'] = '';
        return;
      }
      this.maskedPassword = '*'.repeat(target.value.length);
      this.actualPassword = target.value;
      this.model['password'] = target.value;
    },
    async submitFrom() {
      try {
        if (!this.validateForm()) {
          // Name the inputs, so "Field is required" never again points at
          // nothing the user can see (DOCB-14502).
          const names = this.missingFields
            .map((key: string) => this.$t(REQUIRED_FIELDS[key]))
            .join(', ');
          notify.error(
            names ? `${this.$t('FIELD_REQUIRED')}: ${names}` : this.$t('FIELD_REQUIRED'),
          );
          return;
        }
        this.loading = true;
        const response = await importApiService.ftpImportAddUpdate(
          this.prepareApiData(),
        );

        if (!response.success) {
          throw response;
        }

        if (response.data.hasOwnProperty('id')) {
          this.row_id = response.data.id;
        }
        notify.success(this.$t('MSG_SAVE'));
        await this.checkConnection();
        const event = new CustomEvent('ftp_import_updated', { detail: {} });
        document.dispatchEvent(event);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    validateForm() {
      let validate = true;
      this.validationTriggered = true;
      this.resetErrors();
      this.syncPasswordFromInput();

      // if (!this.model['default_directory']) {
      //   validate = false;
      //   this.errors['default_directory'] = true;
      //   notify.error(this.$t('FIELD_REQUIRED'));
      // }

      // DOCB-14502: validate the form's own required inputs, not the model.
      //
      // In edit mode the model is the row GET /ftp_import/list returns — every
      // column of the service's `ftp_import_configuration` table, not only the
      // fields this form renders. The previous exclude list had to name each
      // hidden column, and every column the service gained afterwards
      // (`token`, then `delete_after_import` for DOCB-14389) made a fully
      // populated form fail with "Field is required" and nothing to fix.
      // Naming what IS required cannot go stale the same way.
      this.missingFields = [];
      for (const key of Object.keys(REQUIRED_FIELDS)) {
        if (key === 'password' && this.hasStoredPassword) {
          continue; // kept by the service unless a new one is typed
        }
        const value = this.model[key];
        if (!value || String(value).length == 0) {
          validate = false;
          this.errors[key] = true;
          this.missingFields.push(key);
        }
      }

      if (!this.validateArchiveDirectory()) {
        validate = false;
      }

      if (!this.validateRetrySettings()) {
        validate = false;
      }

      return validate;
    },

    // CORE-1468: ranges from the solution design; the service enforces the
    // same limits, this just saves the round trip.
    validateRetrySettings() {
      let valid = true;
      const interval = Number(this.model['retry_interval']);
      if (!Number.isFinite(interval) || interval < 5 || interval > 1440) {
        this.errors['retry_interval'] = true;
        notify.error(
          this.$t(
            'retry_interval_out_of_range',
            'Retry interval must be between 5 and 1440 minutes',
          ),
        );
        valid = false;
      }
      const duration = Number(this.model['retry_duration']);
      if (!Number.isFinite(duration) || duration < 1 || duration > 168) {
        this.errors['retry_duration'] = true;
        notify.error(
          this.$t(
            'retry_duration_out_of_range',
            'Retry duration must be between 1 and 168 hours',
          ),
        );
        valid = false;
      }
      const emails = String(this.model['notification_emails'] || '')
        .split(/[,;]/)
        .map((e: string) => e.trim())
        .filter((e: string) => e.length > 0);
      const invalid = emails.filter(
        (e: string) => !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e),
      );
      if (invalid.length > 0) {
        this.errors['notification_emails'] = true;
        notify.error(
          `${this.$t(
            'invalid_notification_emails',
            'Invalid notification email(s)',
          )}: ${invalid.join(', ')}`,
        );
        valid = false;
      }
      return valid;
    },

    validateArchiveDirectory() {
      if (!this.model.destination_directory) {
        return true;
      }

      const archivePath = this.model.destination_directory.trim();
      const importPath = this.model.import_directory?.trim() || '';
      const defaultPath = this.model.default_directory.trim();

      if (this.model.include_subfolder_content) {
        if (importPath && this.isSubPath(archivePath, importPath)) {
          this.errors['destination_directory'] = true;
          notify.error(this.$t('archive_inside_import_path'));
          return false;
        }
        if (!importPath && this.isSubPath(archivePath, defaultPath)) {
          this.errors['destination_directory'] = true;
          notify.error(this.$t('archive_inside_default_path'));
          return false;
        }
      }
      return true;
    },

    isSubPath(childPath: string, parentPath: string) {
      return childPath.startsWith(parentPath + '/');
    },

    prepareApiData() {
      let encrypted_password = this.passwordForApi();
      this.model.ignore_certificate = this.model.ignore_certificate
        ? true
        : false;
      return {
        password: encrypted_password, // this.model.password,
        username: this.model.username,
        server: this.model.server,
        port: this.model.port,
        ftp_type: this.model.ftp_type,
        file_name_matching_patterns: this.model.file_name_matching_patterns,
        api_key: this.api_key,
        sub_org_id: this.model.sub_org_id,
        id: this.row_id,
        ignore_certificate: this.model.ignore_certificate,
        default_directory: this.model.default_directory,
        move_after_import: this.model.move_after_import,
        destination_directory: this.model.destination_directory,
        include_subfolder_content: this.model.include_subfolder_content,
        import_directory: this.model.import_directory,
        additional_attributes: this.model.additional_attributes || '',
        // CORE-1468: retry settings + deactivation notification recipients.
        retry_interval: Number(this.model.retry_interval) || 60,
        retry_duration: Number(this.model.retry_duration) || 48,
        notification_emails: String(
          this.model.notification_emails || '',
        ).trim(),
      };
    },

    /**
     * CORE-6168: only a password the user typed is encrypted and sent. An
     * untouched stored one goes back exactly as an older service returned it,
     * or empty, which the service reads as "keep the stored password".
     */
    passwordForApi() {
      this.syncPasswordFromInput();
      if (this.actualPassword) {
        return this.encryptPassword().toString();
      }
      return this.storedPassword;
    },

    // todo: Fix password encrption
    encryptPassword() {
      var key = enc.Utf8.parse(this.EMAIL_ENCRYPTION_KEY);
      var encrypted = AES.encrypt(this.actualPassword, key, {
        mode: mode.ECB,
        padding: pad.Pkcs7,
      });
      return encrypted;
    },

    updateFTPImportEvent() {
      const event = new CustomEvent('email_import_updated', {});
      document.dispatchEvent(event);
    },

    async checkConnection() {
      try {
        if (!this.row_id) {
          return;
        }
        this.loading = true;
        const response = await importApiService.ftpConnectionTest(this.row_id);
        if (
          !response ||
          (response.hasOwnProperty('success') && response.success === false)
        ) {
          throw response;
        }

        notify.success(this.$t('test_connection_success'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    resetErrors() {
      for (const [key, value] of Object.entries(this.model)) {
        this.errors[key] = false;
      }
    },

    filterSubOrgslistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filterSubOrgsList = this.subOrgList;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filterSubOrgsList = this.subOrgList.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    onDocTypeChange(value: string | null) {
      if (value) {
        this.model['additional_attributes'] = JSON.stringify({ doc_type: value });
      } else {
        this.model['additional_attributes'] = '';
      }
    },

    toggleArchiveImport() {
      this.model.move_after_import = !this.model.move_after_import;
    },

    toggleIgnoreCertificate() {
      this.model.ignore_certificate = !this.model.ignore_certificate;
    },

    toggleSubfolderContentSetting() {
      this.model.include_subfolder_content =
        !this.model.include_subfolder_content;
    },

    async fetchFolders() {
      if (!this.row_id) return; //No get folders request should be made on config creation
      this.folderOptionsLoading = true;
      try {
        const response = await importApiService.getFTPFolders(this.row_id);
        this.folderOptions = response;
      } catch (err) {
        // DOCB-14502: the service now refuses a primary directory the server
        // does not have; the user must see that instead of an empty picker,
        // and a list from an earlier, working directory must not linger.
        this.folderOptions = [];
        notify.error(ApiExceptions.getErrorMessage(err as dynamicObj));
        logError('Error fetching folders:', err);
      } finally {
        this.folderOptionsLoading = false;
      }
    },
  },
});
</script>
