          </div>

          <!-- Error Notifications Section -->
          <div class="wizard-section q-mb-sm" data-test="email-error-notification-email">
            <div class="wizard-section-header q-mb-md">
              <q-icon name="error_outline" size="20px" class="section-icon section-icon-error" />
              <div>
                <div class="section-title">{{ $t('error_notifications') }}</div>
                <div class="section-subtitle">{{ $t('error_notifications_desc') }}</div>
              </div>
            </div>

            <div class="field-label">{{ $t('error_notification_email') }}</div>
            <q-input
              v-model="model['error_notification_email']"
              :placeholder="$t('error_email_placeholder')"
              outlined
              dense
              hide-bottom-space
            >
              <template v-slot:prepend>
                <q-icon name="mail_outline" size="18px" color="grey-6" />
              </template>
            </q-input>
          </div>

          <!-- Document Routing Section -->
          <div class="wizard-section q-mb-sm">
            <div class="wizard-section-header q-mb-md">
              <q-icon name="alt_route" size="20px" class="section-icon" />
              <div>
                <div class="section-title">{{ $t('email_route') }}</div>
                <div class="section-subtitle">{{ $t('email_route_desc') }}</div>
              </div>
            </div>

            <q-select
              v-model="model['email_route']"
              :options="emailRouteOptions"
              outlined
              dense
              hide-bottom-space
              emit-value
              map-options
            >
              <template v-slot:prepend>
                <q-icon name="alt_route" size="18px" color="grey-6" />
              </template>
            </q-select>

            <!-- SMTP config for automatic replies (IMAP + DocNet only — OAuth uses Graph API) -->
            <div v-if="model['email_route'] === 'docnet' && !Office365_selected && !Office365_tenant_selected" class="wizard-section q-mb-sm q-mt-lg">
              <div class="wizard-section-header q-mb-md">
                <q-icon name="reply" size="20px" class="section-icon" />
                <div>
                  <div class="section-title">{{ $t('smtp_config') }}</div>
                  <div class="section-subtitle">{{ $t('smtp_config_desc') }}</div>
                </div>
              </div>

              <div class="row q-col-gutter-md">
                <div class="col-12">
                  <div class="field-label">{{ $t('smtp_server') }}</div>
                  <q-input
                    v-model="model['smtp_server']"
                    placeholder="smtp.example.com"
                    outlined
                    dense
                    hide-bottom-space
                  />
                </div>

                <div class="col-6">
                  <div class="field-label">{{ $t('smtp_port') }}</div>
                  <q-input
                    v-model="model['smtp_port']"
                    placeholder="587"
                    outlined
                    dense
                    hide-bottom-space
                  />
                </div>
              </div>

            </div>
          </div>

          <!-- Advanced Settings Section -->
          <div class="wizard-section q-mb-sm">
            <q-expansion-item
              v-model="advancedSettingsExpanded"
              header-class="advanced-settings-header"
              expand-icon-class="text-grey-6"
            >
              <template v-slot:header>
                <div class="wizard-section-header">
                  <q-icon name="settings" size="20px" class="section-icon" />
                  <div>
                    <div class="section-title">{{ $t('advanced_settings') }}</div>
                    <div class="section-subtitle">{{ $t('advanced_settings_desc') }}</div>
                  </div>
                </div>
              </template>

              <div class="q-pt-md">
                <div class="option-row">
                  <q-checkbox v-model="model['include_email_details']" dense :label="$t('attach_email_body')" />
                  <q-icon name="info" size="20px" color="primary" class="q-ml-sm" >
                    <q-tooltip>{{ $t('attach_email_body_help') }}</q-tooltip>
                  </q-icon>
                </div>
              </div>
            </q-expansion-item>
          </div>

        </q-step>

        <template v-slot:navigation>
          <q-stepper-navigation class="wizard-navigation">
            <div class="row items-center justify-between full-width">
              <div class="col-auto">
                <!-- Back button for steps > 1 (IMAP/POP3, Office365, and Office365 Tenant) -->
                <q-btn
                  v-if="step > 1"
                  flat
                  color="grey-7"
                  @click="($refs.stepper as any).previous()"
                  :label="$t('back')"
                  icon="chevron_left"
                  class="wizard-back-btn"
                  data-test="email-wizard-back-btn"
                />
                <!-- Cancel button for step 1 -->
                <q-btn
                  v-else
                  flat
                  color="grey-7"
                  v-close-popup
                  :label="$t('cancel')"
                  class="wizard-cancel-btn"
                  data-test="email-cancel-btn"
                />
              </div>

              <div class="col-auto">
                <!-- Next button: IMAP steps 1-2, O365 step 1 (when authenticated) -->
                <q-btn
                  v-if="(!Office365_tenant_selected && !Office365_selected && step < 3) || ((Office365_selected || Office365_tenant_selected) && ms_is_authenticated && step === 1)"
                  @click="goNext()"
                  color="primary"
                  :label="$t('next')"
                  icon-right="chevron_right"
                  unelevated
                  class="wizard-next-btn"
                  data-test="email-wizard-next-btn"
                />
                <!-- Final step buttons -->
                <!-- IMAP/POP3: Save button (step 3) -->
                <f-btn
                  v-if="!Office365_tenant_selected && !Office365_selected && step === 3"
                  type="submit"
                  class="wizard-save-btn"
                  data-test="email-save-btn"
                  :label="$t('save')"
                />
                <!-- O365 & O365 Tenant: Import and Save buttons (step 2) -->
                <template v-if="(Office365_selected || Office365_tenant_selected) && ms_is_authenticated && step === 2">
                  <f-btn appearance="secondary" v-if="row_id" class="q-mr-sm" :label="$t('import_type')" @click="manual_import()"/>
                  <f-btn :label="$t('save')" @click="saveFolder()"/>
                </template>
              </div>
            </div>
          </q-stepper-navigation>
        </template>

      </q-stepper>

    </form>

    <q-inner-loading :showing="loading" class="z-index-1">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { storeToRefs } from 'pinia';
import { useDropdownStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { importApiService } from 'src/services';
import { copyToClipboard } from 'quasar';
import CryptoJS from 'crypto-js';
const { AES, mode, enc, pad } = CryptoJS;
import azureLogin from './azureLogin.vue';
import encryptionUtil from 'src/utils/encryptionUtil';
import { runtimeEnv } from 'src/config/runtime-env';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin, encryptionUtil],
  props: {
    selected_model: {} as any,
    api_key: { type: String, default: '' },
  },
  components: {azureLogin},
  data() {
    return {};
  },
  setup() {
    const dropdown_store = useDropdownStore();
    const { encryptions, protocols, subOrgList, sub_org_list_loading } =
      storeToRefs(dropdown_store);
    const filterSubOrgsList: any = ref(dropdown_store.subOrgList);

    return {
      step: ref(1),
      EMAIL_ENCRYPTION_KEY: ref(''),
      subOrgList,
      sub_org_list_loading,
      filterSubOrgsList,
      protocols,
      encryptions,
      loading: ref(false),
      model: ref({} as any),
      row_id: ref(''),
      errors: ref({} as { [k: string]: any }),
      Office365_selected: ref(false),
      use_folder: ref(false),
      use_email: ref(false),
      delete_after_import: ref(false),
      send_email_after_import: ref(false),
      ms_url: ref('https://microsoft.com/devicelogin'),
      ms_code: ref(''),
      ms_authenticate: ref(false),
      ms_is_authenticated: ref(false),
      ms_message: ref('Microsoft o365 is authenticated already.'),
      api_key_ref: ref(''),
      folder_list: ref([] as any),
      maskedPassword: ref(''), // Store masked version of the password
      actualPassword: ref(''),
      Office365_tenant_selected: ref(false),
      advancedSettingsExpanded: ref(false),
      emailRouteOptions: [] as { label: string; value: string }[],
    };
  },
  mounted: function () {
    const EMAIL_ENCRYPTION_KEY = runtimeEnv('APP_VUE_EMAIL_ENCRYPTION_KEY');
    if (EMAIL_ENCRYPTION_KEY == undefined) {
      throw 'Missing EMAIL_ENCRYPTION_KEY env - unable to load'
    }
    this.EMAIL_ENCRYPTION_KEY = EMAIL_ENCRYPTION_KEY
    this.emailRouteOptions = [
      { label: this.$t('email_route_docbits'), value: 'docbits' },
      { label: this.$t('email_route_docnet'), value: 'docnet' },
    ];
    this.initView();
  },

  methods: {
    async initView() {
      this.api_key_ref = this.api_key;

      this.row_id = this.selected_model.hasOwnProperty('id')
        ? this.selected_model.id
        : '';

      //Only trigger fetch folders if protocol is Non Tenant
      if (this.row_id != '' && this.selected_model.protocol != 'OAuth Office365 - Tenant') {
        await this.getFolders()
      }
      this.folder_list
      this.model = JSON.parse(JSON.stringify(this.selected_model));
      for (let [name, value] of Object.entries(this.model)) {
        if (!value && name == 'merge_pdf_files') {
          this.model[name] = false;
        }
        else if (!value && name == 'delete_after_import') {
          this.model[name] = false;
        }
        else if (!value && name == 'is_active') {
          this.model[name] = false;
        }
        else if (!value && name == 'send_email_after_import') {
          this.model[name] = false;
        }
        else if (!value && name == 'use_filename_filter') {
          this.model[name] = false;
        }
        else if (!value && name == 'scan_body') {
          this.model[name] = false;
        }
        else if (!value && name == 'scan_subject') {
          this.model[name] = false;
        }
        else if (!value && name == 'include_email_details') {
          this.model[name] = false;
        }
        else if (!value && name == 'email_route') {
          this.model[name] = 'docbits';
        }
        else if (!value) {
          this.model[name] = '';
        }
        
      }

      if (!this.model.email_route) {
        this.model.email_route = 'docbits';
      }

      if (!this.model.cloud_instance) {
        this.model.cloud_instance = 'global';
      }

      this.protocolUpdated();
      if (['OAuth Office365', 'OAuth Office365 - Tenant'].includes(String(this.model.protocol))) {
        this.ms_is_authenticated = true;

        if (
          this.model.shared_email != 'null' &&
          this.model.shared_email != null &&
          this.model.shared_email != ''
        ) {
          this.use_email = true;
        } else {
          this.model.shared_email = '';
          this.use_email = false;
        }

        if (this.model.folder != 'null' && this.model.folder != '') {
          this.use_folder = true;
        } else {
          this.model.folder = '';
          this.use_folder = false;
        }
      }

      if (this.model.move_to_folder != 'null' && this.model.move_to_folder != '' && this.model.move_to_folder != null) {
        this.model.delete_after_import = true;
      } else {
        this.model.move_to_folder = '';
        this.model.delete_after_import = false;
      }

      if (!this.model.hasOwnProperty('service_type')) {
        this.model.service_type = 'Other';
      }

      if (this.model['password'] && this.model['password'] !== '') {
        this.actualPassword = this.decryptPassword(this.model['password']).toString(enc.Utf8);
        this.maskedPassword = '*'.repeat(this.actualPassword.length);
      }

      if (!this.row_id) {
        this.resetForm();
      }
    },

    resetForm() {
      this.model = {
        port: '',
        email: '',
        server: '',
        folder: '',
        skip: false,
        username: '',
        password: '',
        protocol: '',
        active: false,
        encryption: '',
        sub_org_id: '',
        email_body: '',
        shared_email: '',
        email_subject: '',
        whole_email: false,
        service_type: 'Other',
        merge_pdf_files: false,
        use_filename_filter: false,
        include_email_details: false,
        delete_after_import: false,
        error_notification_email: '',
        send_email_after_import: false,
        scan_body: false,
        scan_subject: false,
        email_route: 'docbits',
        cloud_instance: 'global',
      };
    },

    copyPassword(){
      this.maskedPassword = '*'.repeat(this.actualPassword.length);
      navigator.clipboard.writeText(this.actualPassword).then(() => {
        notify.success(this.$t('password_copy_msg'));
      });
    },

    copyApiKey() {
      copyToClipboard(this.api_key_ref).then(() => {
        notify.success(this.$t('api_key_copied'));
      });
    },

    handleFocus(event: Event) {
        this.maskedPassword = '';
    }, 
    handleBlur(event: Event) {
        const target = event.target as HTMLInputElement;
        this.maskedPassword = '*'.repeat(target.value.length);
        this.actualPassword = target.value;
        this.model.value['password'] = target.value;
    },  
    async submitFrom() {
      try {
        
        this.loading = true;
        if (this.model.protocol == 'OAuth Office365') {
          this.updateModel();
        }
        const response = await importApiService.AddUpdateEmail(
          this.prepareApiData()
        );

        if (!response.success) {
          throw response.message;
        }
        notify.success(this.$t('MSG_SAVE'));
        if (this.model.protocol !== 'OAuth Office365') {
          this.resetForm();
          this.updateEmailImportEvent();
          return;
        }

        if (
          this.model.protocol == 'OAuth Office365' &&
          response.hasOwnProperty('code')
        ) {
          this.model = response.data;
          this.row_id = this.model.id;
          this.ms_code = response.code;
          this.openMsPage();
          this.ms_authenticate = true;
          // Ensure boolean fields have default values
          this.model.include_email_details = this.model.include_email_details ?? false;
          this.model.merge_pdf_files = this.model.merge_pdf_files ?? false;
          this.model.use_filename_filter = this.model.use_filename_filter ?? false;
          this.model.delete_after_import = this.model.delete_after_import ?? false;
          this.model.send_email_after_import = this.model.send_email_after_import ?? false;
        }

        if (
          this.model.protocol == 'OAuth Office365 - Tenant'
        ) {
        }
        const event = new CustomEvent('record_saved', { detail: {} });
        document.dispatchEvent(event);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    prepareApiData() {
      let encrypted = this.encryptPassword()
      let data: dynamicObj = {
        email: this.model.email,
        shared_email: this.model.shared_email,
        password: encrypted,
        username: this.model.username,
        server: this.model.server,
        port: this.model.port,
        encryption: this.model.encryption,
        protocol: this.model.protocol,
        whole_email:
          this.model.whole_email === '' ? false : this.model.whole_email,
        skip: this.model.skip === '' ? false : this.model.skip,
        api_key: this.api_key,
        sub_org_id: this.model.sub_org_id,
        folder:
          this.model.encryption != 'SSL' || this.model.protocol != 'IMAP'
            ? ''
            : this.model.folder,

        email_body: this.model.email_body,
        email_subject: this.model.email_subject,
        merge_pdf_files: this.model.merge_pdf_files,
        use_filename_filter: this.model.use_filename_filter,
        include_email_details: this.model.include_email_details,
        delete_after_import: this.model.delete_after_import,
        send_email_after_import: this.model.send_email_after_import,
        error_notification_email: this.model.error_notification_email,
        move_to_folder: this.model.delete_after_import == true ? this.model.move_to_folder : '',
        scan_body: this.model.scan_body,
        scan_subject: this.model.scan_subject,
        email_route: this.model.email_route || 'docbits',
        smtp_server: this.model.smtp_server ?? '',
        smtp_port: this.model.smtp_port ?? '',
        tenant_id : this.generalEncryption(this.model.tenant_id) ?? null,
        app_id : this.generalEncryption(this.model.app_id) ?? null,
        client_value : this.generalEncryption(this.model.client_value) ?? null,
        cloud_instance : this.model.cloud_instance || 'global',
      }

      if (this.row_id) {
        data['id'] = this.row_id;
      }
      return data;
    },

    // todo: Fix password encrption
    encryptPassword() {
      var key = enc.Utf8.parse(this.EMAIL_ENCRYPTION_KEY)
      var encrypted = AES.encrypt(this.actualPassword, key, {
        mode: mode.ECB,
        padding: pad.Pkcs7,
      })
      return encrypted
    },

    // todo: Fix password decrption
    decryptPassword(password: string) {
      var key = enc.Utf8.parse(this.EMAIL_ENCRYPTION_KEY)
      var decrypted =  AES.decrypt(password, key, {mode:mode.ECB});
      return decrypted
    },

    updateModel() {
      this.model.password = '';
      this.model.username = '';
      this.model.server = '';
      this.model.port = '';
      this.model.encryption = '';
      this.model.folder = '';
      this.model.email_body = '';
      this.model.email_subject = '';
      this.model.shared_email = null;
      this.model.sub_org_id = null;
    },

    copyText() {
      copyToClipboard(this.ms_code).then(() => {
        notify.success('Copied!');
      });
    },

    updateEmailImportEvent() {
      const event = new CustomEvent('email_import_updated', {});
      document.dispatchEvent(event);
    },

    openMsPage() {
      window.open(this.ms_url, '_blank');
    },

    protocolUpdated() {
      if (this.model.protocol == 'OAuth Office365') {
        this.Office365_selected = true;
        this.Office365_tenant_selected = false;
      } else if (this.model.protocol == 'OAuth Office365 - Tenant') {
        this.Office365_tenant_selected = true;
        this.Office365_selected = false;
      } else{
        this.Office365_selected = false;
        this.Office365_tenant_selected = false;
      }
    },

    async msfinish() {
      try {
        this.loading = true;
        const response = await importApiService.finishMsAuth(this.row_id);
        if (response.success == true) {
          this.ms_is_authenticated = true;
          notify.success(this.$t('Authentication completed'));
        }
      } catch {
        notify.error(
          this.$t('Something failed on the transmission_ Please try again_')
        );
      } finally {
        this.loading = false;
      }
    },

    async manual_import() {
      this.loading = true
      
      await importApiService.performManuelImportMail(this.row_id);
      this.loading = false
      notify.success(this.$t('import_try'));
      this.$router.push('/dashboard');
    },

    validateLoginTest() {
      let validate = true;
      this.resetErrors();
      const exclude_fields = ['folder', 'whole_email', 'skip', 'active'];

      if (this.model.protocol === 'OAuth Office365') {
        validate = false;
        notify.error(this.$t('service_type_not_supported'));
        return validate;
      }

      for (const [key, value] of Object.entries(this.model)) {
        if (exclude_fields.includes(key)) {
          continue;
        }

        if (!value || String(value).length == 0) {
          validate = false;
          this.errors[key] = true;
        }
      }

      return validate;
    },

    resetErrors() {
      for (const [key, value] of Object.entries(this.model)) {
        this.errors[key] = false;
      }
    },

    goNext() {
      if (!this.validateStep(this.step)) {
        notify.error(this.$t('please_fill_all_mandatory_fields'));
        return;
      }
      (this.$refs.stepper as any).next();
    },

    validateStep(currentStep: number): boolean {
      this.resetErrors();
      const requiredFields = this.getRequiredFieldsForStep(currentStep);
      if (requiredFields.length === 0) {
        return true;
      }

      let valid = true;
      for (const field of requiredFields) {
        const value =
          field === 'password' ? this.actualPassword : this.model[field];
        if (value === undefined || value === null || String(value).trim() === '') {
          this.errors[field] = true;
          valid = false;
        }
      }
      return valid;
    },

    getRequiredFieldsForStep(currentStep: number): string[] {
      if (currentStep === 1) {
        if (this.Office365_selected || this.Office365_tenant_selected) {
          return ['protocol'];
        }
        return [
          'protocol',
          'server',
          'port',
          'encryption',
          'username',
          'email',
          'password',
        ];
      }
      return [];
    },

    async saveFolder() {
      try {
        this.loading = true;
        const data = {
          id: this.row_id,
          folder: this.use_folder == true ? this.model.folder : 'null',
          shared_email: this.use_email == true ? this.model.shared_email : 'null',
          sub_org_id: this.model.sub_org_id,
          delete_after_import: this.model.delete_after_import,
          move_to_folder: this.model.move_to_folder,
          error_notification_email: this.model.error_notification_email,
          include_email_details: this.model.include_email_details ?? false,
          email_route: this.model.email_route || 'docbits',
        };
        let response = await importApiService.saveFolder(data);
        if (!response.success) {
          throw response;
        }
        notify.success(this.$t('MSG_SAVE'));
        this.resetForm();
        this.updateEmailImportEvent();

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async getFolders() {
      try {
        this.loading = true;

        let response = await importApiService.getFolders(this.row_id, this.model.shared_email as string | null);
        if (!response.success) {
          throw response;
        }

        this.folder_list = response.data

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    filterSubOrgslistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filterSubOrgsList = this.subOrgList;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filterSubOrgsList = this.subOrgList.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1
        );
      });
    },

    copyToClipboard() {
      navigator.clipboard.writeText(this.receiveEmail)
        .then(() => {
          notify.success(this.$t('success_copy_to_clipboard'))
        })
        .catch((err) => {
          notify.error(this.$t('error_copy_to_clipboard'))
        });
    },

    createTenantConfig(tenant_id: string, app_id: string, client_value: string, cloud_instance = 'global') {
      this.model.tenant_id = tenant_id;
      this.model.app_id = app_id;
      this.model.client_value = client_value;
      this.model.cloud_instance = cloud_instance;
      // Ensure boolean fields have default values
      this.model.include_email_details = this.model.include_email_details ?? false;
      this.model.merge_pdf_files = this.model.merge_pdf_files ?? false;
      this.model.use_filename_filter = this.model.use_filename_filter ?? false;
      this.model.delete_after_import = this.model.delete_after_import ?? false;
      this.model.send_email_after_import = this.model.send_email_after_import ?? false;
      this.submitFrom();
    }
  },
});
</script>

<style scoped lang="scss">
