<template>
  <docbits-accordion-panel
    :modelValue="modelValue"
    icon="mdi:email-arrow-right"
    :title="$t('settings_email_import')"
    bodyClass="settings-card"
    data-test="sa-email-import"
    @update:modelValue="$emit('update:modelValue', $event)"
  >
    <template #header-actions>
      <f-btn
        icon="add"
        :label="$t('new')"
        data-test="email-new-btn"
        @click="createNewRecord"
      />
      <f-btn square class="q-ml-sm" @click="showMailImportLogs(0)" invert>
        <Icon icon="mdi:text-box-multiple" width="20" height="20" />
        <q-tooltip>{{ $t('import_log') }}</q-tooltip>
      </f-btn>
    </template>

    <div class="row items-center q-pa-sm q-mb-sm">
      <div class="col">
        <span>{{ $t('email_info') }}</span>
        <a
          @click="webSiteLink"
          class="cursor-pointer color-primary q-ml-xs"
          target="_blank"
        >
          {{ $t('email_link') }}
        </a>
      </div>
    </div>

    <div class="row">
      <DocBitsTable
        :rows="rows"
        :columns="columns"
        row-key="name"
        table-id="email_import_table"
        table-height="500px"
        :loading="loading"
        :features="{
          sorting: false,
          filtering: false,
          selection: false,
          bulkActions: false,
          rowActions: true,
          resizable: false,
          pagination: false,
          columnReorder: true,
          stickyLastColumn: true,
        }"
        :row-actions="emailRowActions"
        :column-order="columnOrder"
        :row-class="emailRowClass"
        no-data-label="no_record_found"
        flat-style
        @row-action="handleRowAction"
        @column-reorder="handleColumnReorder"
      >
        <template #body-cell-sub_org_id="{ row }">
          <span>{{ sub_orgs_flattened[row.sub_org_id] }}</span>
        </template>
        <template #body-cell-folder="{ row }">
          <span
            class="truncate max-w-[200px] inline-block"
            :title="row.folder"
            >{{ row.folder }}</span
          >
        </template>
        <template #body-cell-email_route="{ row }">
          <span>{{
            row.email_route ? $t('email_route_' + row.email_route) : ''
          }}</span>
        </template>
      </DocBitsTable>
    </div>
  </docbits-accordion-panel>

  <q-inner-loading :showing="loading" class="z-index-1" style="z-index: 1000">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>

  <!-- create edit dialog -->
  <q-dialog
    v-model="show_edit_create"
    persistent
    @keydown.esc="show_edit_create = false"
  >
    <EditCreateNew :selected_model="selected_row" :api_key="api_key" />
    <EditCreateOld
      v-if="false"
      :selected_model="selected_row"
      :api_key="api_key"
    />
  </q-dialog>

  <q-dialog v-model="show_connection_logs">
    <ConnectionLogs
      :connection_id="connection_id"
      :connection_type="connection_type"
    ></ConnectionLogs>
  </q-dialog>

  <ImportLogs
    :connection_id="connection_id"
    :show_import_logs="show_import_logs"
    :setheight="'36px'"
  />
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { LocalStorage } from 'quasar';
import ImportLogs from './ImportLogs.vue';
import { defineComponent, ref } from 'vue';
import { getLink } from 'src/utils/helpLinks';
import ConnectionLogs from './ConnectionLogs.vue';
import { useDropdownStore } from 'src/store/main';
import subscription from 'src/utils/subscription';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import { importApiService, userApiService } from 'src/services';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import EditCreateOld from 'src/pages/Settings/Components/Import/EmailImportEditCreate.vue';
import EditCreateNew from 'src/pages/Settings/Components/Import/EmailImportFormWizardView.vue';
import type {
  RowActionItem,
  UnifiedTableColumn,
} from 'src/components/Table/types/table/unified-table';

import { runtimeEnv } from 'src/config/runtime-env';
export default defineComponent({
  mixins: [helperMixin, subscription],
  props: {
    modelValue: {
      type: Boolean,
      default: true,
    },
  },
  emits: ['update:modelValue'],
  components: {
    ImportLogs,
    EditCreateOld,
    EditCreateNew,
    ConnectionLogs,
    DocBitsTable,
  },
  watch: {
    sub_org_list_loading(new_val: any, old_val: any) {
      if (new_val === false) {
        this.initView();
      }
    },
  },
  mounted: function () {
    const EMAIL_ENCRYPTION_KEY = runtimeEnv('APP_VUE_EMAIL_ENCRYPTION_KEY');
    if (EMAIL_ENCRYPTION_KEY == undefined) {
      notify.error('Missing an important value - unable to load email import');
      return;
    }
    this.EMAIL_ENCRYPTION_KEY = EMAIL_ENCRYPTION_KEY;

    document.addEventListener('email_import_updated', this.emailImportUpdated);
    document.addEventListener('hide_import_logs', this.onImportLogPopupClose);
    this.handleSubOrgs();
  },

  unmounted: function () {
    document.removeEventListener(
      'email_import_updated',
      this.emailImportUpdated,
    );
    document.removeEventListener(
      'hide_import_logs',
      this.onImportLogPopupClose,
    );
  },

  methods: {
    showMailConnectionLogs(id: any) {
      this.connection_type = 'email_import';
      this.connection_id = id;
      this.show_connection_logs = true;
    },
    showMailImportLogs(id: any) {
      this.show_import_logs = false;
      this.connection_id = id;
      this.show_import_logs = true;
      console.info('showMailImportLogs', id);
    },
    onImportLogPopupClose() {
      this.show_import_logs = false;
    },
    async initView() {
      try {
        this.loading = true;
        this.prepareColumns();
        await this.getAppKey();
        this.flattenSubOrgs();
        this.getList();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    handleSubOrgs() {
      if (this.subOrgList.length > 1) {
        this.initView();
      }
      if (this.sub_org_list_loading) {
        this.loading = true;
      }
    },

    async getList() {
      try {
        this.loading = true;
        this.prepareColumns();
        const response = await importApiService.getList();

        // An empty response must still clear the table: bailing out early left
        // the last deleted connection on screen after a refresh — DG-126.
        this.prepareRows(response?.data || []);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    prepareRows(data: any) {
      this.rows = [] as any;
      Array.from(data).forEach((item: any) => {
        const row = item as dynamicObj;
        this.addNewRow(row);
      });
    },

    addNewRow(row: any) {
      let newRow: dynamicObj = { ...row };
      this.rows.push(newRow);
      return this.rows.length.toString() as string;
    },

    createNewRecord() {
      this.selected_row = {};
      this.show_edit_create = true;
    },

    emailImportUpdated() {
      this.show_edit_create = false;
      this.getList();
    },

    editRow(index: number, row: any) {
      this.selected_row = JSON.parse(JSON.stringify(row));
      this.show_edit_create = true;
    },

    async deleteClicked(index: number, id: number) {
      try {
        this.loading = true;
        const response = await importApiService.deleteRecord(id);
        // The backend can refuse a delete and answer `{ success: false }`
        // (e.g. the import-email-service rejects removing the configuration).
        // Reporting success in that case hid the failure until the next page
        // load, where the connection reappeared — DG-126.
        if (!response || response.success !== true) {
          throw response;
        }
        notify.success(this.$t('success'));
        // Re-read the server state instead of splicing the local array, so the
        // table always shows what the backend actually stores.
        await this.getList();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async getAppKey() {
      try {
        this.loading = true;
        const data = {
          app_key: 'FELLOW_DOC2',
        };
        const response = await userApiService.getAppSubscription(data);
        // A fresh auth realm (e.g. a US-region session whose org has no
        // FELLOW_DOC2 subscription there yet) legitimately returns an empty
        // list — an empty app key must not crash the whole Import settings
        // page with "Cannot read properties of undefined (reading 'token')".
        this.api_key = (Array.isArray(response) && response[0]?.token) || '';
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async de_activateEmail(row: any) {
      try {
        this.loading = true;
        const id = row.id;
        const active = row.is_active;

        if (active) {
          const data = new FormData();
          data.set('email', row.email);
          if (row.folder !== null) {
            data.set('folder', row.folder);
          }

          const response = await importApiService.checkDuplicateConfig(data);
          if (response.data) {
            row.is_active = false;
            notify.error(this.$t('already_active_config_found'));
            return;
          }
        }
        const response = await importApiService.DeActivateEmail(id, active);
        notify.success(this.$t('success'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async checkLogin(row: any) {
      try {
        this.loading = true;
        const response = await importApiService.testEmailLogin(String(row.id));
        if (
          !response ||
          (response.hasOwnProperty('success') && response.success === false)
        ) {
          throw response;
        }

        notify.success(this.$t('check_login_success'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    flattenSubOrgs() {
      this.subOrgList.forEach((item: any) => {
        this.sub_orgs_flattened[item.value] = item.label;
      });
    },

    prepareColumns() {
      this.columns = [
        {
          name: 'username',
          label: this.$t('username'),
          field: 'username',
          align: 'left',
        },
        {
          name: 'email',
          label: this.$t('email'),
          field: 'email',
          align: 'left',
        },
        {
          name: 'shared_email',
          label: this.$t('shared_email'),
          field: 'shared_email',
          align: 'left',
        },
        {
          name: 'protocol',
          label: this.$t('protocol'),
          field: 'protocol',
          align: 'left',
        },
        {
          name: 'encryption',
          label: this.$t('encryption'),
          field: 'encryption',
          align: 'left',
        },
        {
          name: 'sub_org_id',
          label: this.$t('sub_organizations'),
          field: 'sub_org_id',
          align: 'left',
        },
        {
          name: 'folder',
          label: this.$t('folder'),
          field: 'folder',
          align: 'left',
        },
        {
          name: 'email_route',
          label: this.$t('email_route'),
          field: 'email_route',
          align: 'left',
        },
      ] as UnifiedTableColumn[];

      // Restore saved column order
      const saved_columns = LocalStorage.getItem(
        'EMAIL_IMPORT_SETTING_COLUMNS',
      ) as string;
      if (saved_columns) {
        try {
          const parsed = JSON.parse(saved_columns);
          this.columnOrder = parsed
            .map((c: any) => c.name)
            .filter((n: string) => n !== 'action');
        } catch {
          // ignore
        }
      }
    },
    handleColumnReorder(newOrder: string[]) {
      this.columnOrder = newOrder;
      const orderedColumns = newOrder
        .map((name: string) => this.columns.find((c: any) => c.name === name))
        .filter(Boolean);
      LocalStorage.set(
        'EMAIL_IMPORT_SETTING_COLUMNS',
        JSON.stringify(orderedColumns),
      );
    },
    handleRowAction({ action, row }: { action: string; row: any }) {
      const index = this.rows.findIndex((r: any) => r.id === row.id);
      switch (action) {
        case 'test_connection':
          this.checkLogin(row);
          break;
        case 'connection_logs':
          this.showMailConnectionLogs(row.id);
          break;
        case 'import_logs':
          this.showMailImportLogs(row.id);
          break;
        case 'activate':
          row.is_active = true;
          this.de_activateEmail(row);
          break;
        case 'deactivate':
          row.is_active = false;
          this.de_activateEmail(row);
          break;
        case 'edit':
          this.editRow(index, row);
          break;
        case 'delete':
          if (index !== -1) this.deleteClicked(index, row.id);
          break;
      }
    },

    emailRowClass(row: any) {
      return row.is_active ? '' : 'disabled-row';
    },

    webSiteLink() {
      const web_site_link = getLink('import_settings');
      if (!web_site_link) {
        return;
      }
      window.open(web_site_link);
    },
  },

  setup() {
    const dropdown_store = useDropdownStore();
    const { subOrgList, sub_org_list_loading } = storeToRefs(dropdown_store);

    let import_email = ref({} as { [k: string]: any });

    const myForm = ref(null);
    return {
      sub_org_list_loading,
      subOrgList,
      myForm,
      import_email,
      errors: ref({} as { [k: string]: any }),
      show_connection_logs: ref(false),
      show_import_logs: ref(false),
      connection_type: ref(''),
      connection_id: ref(0),
      sub_orgs_flattened: ref({} as dynamicObj),
      processing: ref(false),
      ms_url: ref('https://microsoft.com/devicelogin'),
      ms_code: ref(''),
      ms_authenticate: ref(false),
      ms_is_authenticated: ref(false),
      ms_message: ref('Microsoft o365 is authenticated already.'),
      loading: ref(false),

      userDialog: ref(false),

      columns: ref([] as UnifiedTableColumn[]),
      columnOrder: ref([] as string[]),
      emailRowActions: [
        {
          key: 'test_connection',
          label: 'test_connection',
          icon: 'wifi',
          show: (row: any) =>
            row.protocol === 'IMAP' || row.protocol === 'POP3',
        },
        { key: 'connection_logs', label: 'connection_logs', icon: 'article' },
        { key: 'import_logs', label: 'import_log', icon: 'history' },
        {
          key: 'activate',
          label: 'activate',
          icon: 'check_circle',
          separator: true,
          show: (row: any) => !row.is_active,
        },
        {
          key: 'deactivate',
          label: 'deactivate',
          icon: 'cancel',
          separator: true,
          show: (row: any) => row.is_active,
        },
        { key: 'edit', label: 'edit', icon: 'edit' },
        {
          key: 'delete',
          label: 'delete',
          icon: 'delete',
          color: 'negative',
          separator: true,
        },
      ] as RowActionItem[],
      rows: ref([] as any),
      show_edit_create: ref(false),
      selected_row: ref({} as any),
      api_key: ref(''),

      EMAIL_ENCRYPTION_KEY: ref(''),
    };
  },
  data() {
    return {};
  },
});
</script>

<style lang="scss">
.main-table {
  height: 100%;
  width: 100%;
  overflow-y: auto;
}

.import-active-toggle.active-toggle {
  height: 26px;
}

.import-active-toggle.active-toggle .slider:before {
  height: 24px;
}
</style>
