    <div class="ml-10">
      <div class="column q-gutter-md">
        <q-input
          v-model="tenant_id"
          :label="$t('infor_tenant_id')"
          outlined
          id="tenant_id"
          class="full-width"
          placeholder="XXXXXXXX-XXXX-XXXX-XXXX-XXXXXXXXXXXX"
