<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { importApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import encryptionUtil from 'src/utils/encryptionUtil';
export default defineComponent({
  name: 'azureLogin',
  mixins: [encryptionUtil],
  components: {},
  props: {
    initialCloudInstance: { type: String, default: 'global' },
  },
  mounted() {
    this.app_id = process.env.MICROSOFT_APP_ID_MAIL;
    this.cloud_instance = this.initialCloudInstance || 'global';
  },
  data() {
    return {
      app_id: '' as string | undefined,
      tenant_id: '',
      client_id: '',
      client_secret: '',
      cloud_instance: 'global',
      cloudInstanceOptions: [
        { label: this.$t('cloud_instance_commercial'), value: 'global' },
        { label: this.$t('cloud_instance_gcc_high'), value: 'usgov' },
      ],
    };
  },
  methods: {
    copyDocbitAppId() {
      navigator.clipboard
        .writeText(String(this.app_id))
        .then(() => {
          notify.success(this.$t('success_copy_to_clipboard'));
        })
        .catch((err) => {
          notify.error(this.$t('error_copy_to_clipboard'));
        });
    },
    validateRequiredFields(): boolean {
      if (!this.tenant_id || !this.tenant_id.trim()) {
        notify.error(
          this.$t('infor_tenant_id') +
            ' ' +
            this.$t('is_required'),
        );
        return false;
      }
      if (!this.client_id || !this.client_id.trim()) {
        notify.error(this.$t('app_id') + ' ' + this.$t('is_required'));
        return false;
      }
      if (!this.client_secret || !this.client_secret.trim()) {
        notify.error(
          this.$t('client_value') + ' ' + this.$t('is_required'),
        );
        return false;
      }
      return true;
    },
    async testConnection() {
      if (!this.validateRequiredFields()) {
        return;
      }

      try {
        const data = new FormData();
        data.set('tenant_id', String(this.generalEncryption(this.tenant_id)));
        data.set('app_id', String(this.generalEncryption(this.client_id)));
        data.set(
          'client_value',
          String(this.generalEncryption(this.client_secret)),
        );
        data.set('cloud_instance', this.cloud_instance);
        const response = await importApiService.testAzureConnection(data);

        if (response && response.success == true) {
          notify.success(this.$t('connection_established_successfully'));
          return;
        }

        if (response && response.success == false) {
          throw response;
        }

        if (!response) {
          notify.error(this.$t('connection_established_unsuccessfull'));
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    saveConnection() {
      if (!this.validateRequiredFields()) {
        return;
      }

      this.$emit(
        'saveTenant',
        this.tenant_id,
        this.client_id,
        this.client_secret,
        this.cloud_instance,
      );
    },
  },
});
</script>

